def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Step 1: Select the solution with the highest crowding distance
    def crowding_distance(solution):
        v1, v2 = solution[1]
        neighbors = [obj for _, obj in archive]
        sorted_v1 = sorted(neighbors, key=lambda x: x[0])
        sorted_v2 = sorted(neighbors, key=lambda x: x[1])

        idx_v1 = sorted_v1.index((v1, v2))
        idx_v2 = sorted_v2.index((v1, v2))

        if len(sorted_v1) <= 1 or len(sorted_v2) <= 1:
            return float('inf')

        if idx_v1 == 0 or idx_v1 == len(sorted_v1) - 1:
            dist_v1 = float('inf')
        else:
            dist_v1 = sorted_v1[idx_v1 + 1][0] - sorted_v1[idx_v1 - 1][0]

        if idx_v2 == 0 or idx_v2 == len(sorted_v2) - 1:
            dist_v2 = float('inf')
        else:
            dist_v2 = sorted_v2[idx_v2 + 1][1] - sorted_v2[idx_v2 - 1][1]

        return min(dist_v1, dist_v2)

    selected_idx = max(range(len(archive)), key=lambda i: crowding_distance(archive[i]))
    base_solution, _ = archive[selected_idx]
    new_solution = base_solution.copy()

    # Step 2: Apply a hybrid local search combining greedy and random selection
    current_weight = np.sum(weight_lst * new_solution)
    n_items = len(weight_lst)

    # Calculate combined utility scores
    combined_utility = (value1_lst + value2_lst) / (weight_lst + 1e-6)

    # Greedy phase: add most promising items
    for _ in range(5):
        candidate_items = np.where(new_solution == 0)[0]
        if len(candidate_items) == 0:
            break

        sorted_items = sorted(candidate_items, key=lambda x: combined_utility[x], reverse=True)

        for item in sorted_items:
            if current_weight + weight_lst[item] <= capacity:
                new_solution[item] = 1
                current_weight += weight_lst[item]
                break

    # Random phase: flip items with probability based on their utility
    for item in range(n_items):
        if random.random() < 0.3:  # 30% chance to flip any item
            if new_solution[item] == 1:
                if current_weight - weight_lst[item] >= 0:
                    new_solution[item] = 0
                    current_weight -= weight_lst[item]
            else:
                if current_weight + weight_lst[item] <= capacity:
                    new_solution[item] = 1
                    current_weight += weight_lst[item]

    # Step 3: Apply a diversity-preserving pruning step
    for _ in range(3):
        # Find items that are redundant in both objectives
        for item in np.where(new_solution == 1)[0]:
            temp_solution = new_solution.copy()
            temp_solution[item] = 0
            temp_weight = np.sum(weight_lst * temp_solution)

            # Check if removing this item maintains feasibility
            if temp_weight <= capacity:
                # Check if the solution is still non-dominated
                temp_v1 = np.sum(value1_lst * temp_solution)
                temp_v2 = np.sum(value2_lst * temp_solution)

                is_dominated = False
                for _, (v1, v2) in archive:
                    if (v1 >= temp_v1 and v2 >= temp_v2) and (v1 > temp_v1 or v2 > temp_v2):
                        is_dominated = True
                        break

                if not is_dominated:
                    new_solution[item] = 0
                    current_weight = temp_weight
                    break

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Step 1: Select the most diverse solution using crowding distance
    def crowding_distance(solutions):
        if len(solutions) < 2:
            return [1.0] * len(solutions)
        distances = []
        for i in range(len(solutions)):
            left = solutions[i-1][1] if i > 0 else solutions[-1][1]
            right = solutions[(i+1)%len(solutions)][1] if i < len(solutions)-1 else solutions[0][1]
            dist = abs(right[0] - left[0]) + abs(right[1] - left[1])
            distances.append(dist)
        return distances

    sorted_archive = sorted(archive, key=lambda x: x[1])
    distances = crowding_distance(sorted_archive)
    selected_idx = np.argmax(distances)
    base_solution, _ = archive[selected_idx]
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * new_solution)

    # Step 2: Cluster items by primary objective contribution
    obj1_items = np.where(value1_lst > value2_lst)[0]
    obj2_items = np.where(value2_lst >= value1_lst)[0]

    # Step 3: Dynamic objective fusion search
    fusion_ratio = min(0.5, len(obj1_items) / (len(obj1_items) + len(obj2_items) + 1e-6))

    # Select clusters to include
    if random.random() < fusion_ratio:
        # Focus on objective 1 cluster
        for item in obj1_items:
            if new_solution[item] == 0 and current_weight + weight_lst[item] <= capacity:
                new_solution[item] = 1
                current_weight += weight_lst[item]
    else:
        # Focus on objective 2 cluster
        for item in obj2_items:
            if new_solution[item] == 0 and current_weight + weight_lst[item] <= capacity:
                new_solution[item] = 1
                current_weight += weight_lst[item]

    # Step 4: Random cluster perturbation
    if random.random() < 0.3:
        # Perturb objective 1 cluster
        for item in obj1_items:
            if random.random() < 0.1:
                if new_solution[item] == 1 and current_weight - weight_lst[item] >= 0:
                    new_solution[item] = 0
                    current_weight -= weight_lst[item]
                elif new_solution[item] == 0 and current_weight + weight_lst[item] <= capacity:
                    new_solution[item] = 1
                    current_weight += weight_lst[item]
    else:
        # Perturb objective 2 cluster
        for item in obj2_items:
            if random.random() < 0.1:
                if new_solution[item] == 1 and current_weight - weight_lst[item] >= 0:
                    new_solution[item] = 0
                    current_weight -= weight_lst[item]
                elif new_solution[item] == 0 and current_weight + weight_lst[item] <= capacity:
                    new_solution[item] = 1
                    current_weight += weight_lst[item]

    # Step 5: Cluster pruning to remove redundant items
    for item in obj1_items:
        if new_solution[item] == 1 and value1_lst[item] < np.median(value1_lst[obj1_items]):
            if current_weight - weight_lst[item] >= 0:
                new_solution[item] = 0
                current_weight -= weight_lst[item]

    for item in obj2_items:
        if new_solution[item] == 1 and value2_lst[item] < np.median(value2_lst[obj2_items]):
            if current_weight - weight_lst[item] >= 0:
                new_solution[item] = 0
                current_weight -= weight_lst[item]

    return new_solution

