def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Step 1: Select the most promising solution using Pareto dominance and crowding distance
    def pareto_dominance(a, b):
        return (a[0] >= b[0] and a[1] > b[1]) or (a[0] > b[0] and a[1] >= b[1])

    def crowding_distance(solutions):
        if len(solutions) < 2:
            return [float('inf')] * len(solutions)

        distances = [0] * len(solutions)
        objectives = np.array([obj for _, obj in solutions])

        for m in range(2):
            sorted_idx = np.argsort(objectives[:, m])
            distances[sorted_idx[0]] = float('inf')
            distances[sorted_idx[-1]] = float('inf')

            for i in range(1, len(solutions)-1):
                if objectives[sorted_idx[-1], m] == objectives[sorted_idx[0], m]:
                    continue
                distances[sorted_idx[i]] += (objectives[sorted_idx[i+1], m] - objectives[sorted_idx[i-1], m]) / (objectives[sorted_idx[-1], m] - objectives[sorted_idx[0], m])

        return distances

    # Find non-dominated solutions
    non_dominated = []
    for i, (sol, obj) in enumerate(archive):
        is_dominated = False
        for j, (_, other_obj) in enumerate(archive):
            if i != j and pareto_dominance(other_obj, obj):
                is_dominated = True
                break
        if not is_dominated:
            non_dominated.append((sol, obj))

    if not non_dominated:
        non_dominated = archive

    # Select solution with best crowding distance
    distances = crowding_distance(non_dominated)
    selected_idx = np.argmax(distances)
    base_solution = non_dominated[selected_idx][0].copy()

    # Step 2: Dynamic objective balancing strategy
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * new_solution)
    objective_priority = random.choice([0, 1])  # Randomly select which objective to prioritize

    # Step 3: Adaptive solution fusion with feasibility check
    for _ in range(5):
        # Calculate potential improvements
        potential_obj1 = np.sum(value1_lst * new_solution) + value1_lst * (1 - new_solution)
        potential_obj2 = np.sum(value2_lst * new_solution) + value2_lst * (1 - new_solution)

        if objective_priority == 0:
            # Prioritize objective 1
            candidate_idx = np.argmax(potential_obj1)
            if weight_lst[candidate_idx] <= capacity - current_weight and new_solution[candidate_idx] == 0:
                new_solution[candidate_idx] = 1
                current_weight += weight_lst[candidate_idx]
        else:
            # Prioritize objective 2
            candidate_idx = np.argmax(potential_obj2)
            if weight_lst[candidate_idx] <= capacity - current_weight and new_solution[candidate_idx] == 0:
                new_solution[candidate_idx] = 1
                current_weight += weight_lst[candidate_idx]

    # Step 4: Pareto-aware mutation operator
    mutation_rate = 0.2 + 0.3 * (1 - current_weight / capacity)  # Higher mutation rate when capacity is more available
    for i in range(len(new_solution)):
        if random.random() < mutation_rate:
            if new_solution[i] == 1:
                new_solution[i] = 0
                current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Step 5: Feasibility-preserving refinement
    while current_weight > capacity:
        remove_idx = np.argmax(weight_lst * new_solution)
        if new_solution[remove_idx] == 1:
            new_solution[remove_idx] = 0
            current_weight -= weight_lst[remove_idx]

    return new_solution

