        utility = obj1_weight * (value1_lst / (weight_lst + 1e-6)) + obj2_weight * (value2_lst / (weight_lst + 1e-6))
        candidate_add = np.where(new_solution == 0)[0]
        if len(candidate_add) > 0:
            sorted_add = sorted(candidate_add, key=lambda x: utility[x], reverse=True)
            for item in sorted_add:
                if current_weight + weight_lst[item] <= capacity:
                    new_solution[item] = 1
                    current_weight += weight_lst[item]
                    break

        # Select items to potentially remove based on weighted utility
        candidate_remove = np.where(new_solution == 1)[0]
        if len(candidate_remove) > 0:
            sorted_remove = sorted(candidate_remove, key=lambda x: utility[x])
            for item in sorted_remove:
