    max_v1 = max(obj[0] for _, obj in archive) if archive else 1.0
    max_v2 = max(obj[1] for _, obj in archive) if archive else 1.0

    # Calculate Pareto dominance scores
    dominance_scores = []
    for sol, obj in archive:
        dominated = False
        dominates = False
        for _, other_obj in archive:
            if other_obj[0] > obj[0] and other_obj[1] >= obj[1]:
                dominated = True
            if other_obj[0] >= obj[0] and other_obj[1] > obj[1]:
                dominated = True
            if other_obj[0] < obj[0] and other_obj[1] <= obj[1]:
                dominates = True
            if other_obj[0] <= obj[0] and other_obj[1] < obj[1]:
                dominates = True
        score = (dominates - dominated) / len(archive) if archive else 0
        dominance_scores.append((score, sol))

    selected_sol = max(dominance_scores, key=lambda x: x[0])[1]
    base_solution = selected_sol.copy()
